class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        m, n = len(grid), len(grid[0])
        DIRS = [(0,1), (1,0), (-1,0), (0,-1)]

        def dfs(r, c):
            if not (0 <= r < m and 0 <= c < n and grid[r][c] == "1"):
                return

            grid[r][c] = "0"
            for d in DIRS:
                nr, nc = r + d[0], c + d[1]
                dfs(nr, nc)

        count = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == "1":
                    count += 1
                    dfs(i, j)
        return count
